raw_commands:
{#- URY KOT for kitchen printers (ESC/POS raw, 80 mm, 48 columns). ASCII only. -#}
{%- set ESC = "\x1B" -%}
{%- set GS = "\x1D" -%}
{%- set INIT = ESC ~ "@" -%}
{%- set LEFT = ESC ~ "a" ~ "\x00" -%}
{%- set CENTER = ESC ~ "a" ~ "\x01" -%}
{%- set BOLD_ON = ESC ~ "E" ~ "\x01" -%}
{%- set BOLD_OFF = ESC ~ "E" ~ "\x00" -%}
{%- set TALL = GS ~ "!" ~ "\x01" -%}
{%- set BIG = GS ~ "!" ~ "\x11" -%}
{%- set PLAIN = GS ~ "!" ~ "\x00" -%}
{%- set CUT = GS ~ "V" ~ "\x41" ~ "\x03" -%}
{%- set LF = "\n" -%}
{%- set W = 48 -%}
{%- set LINE = "-" * W -%}
{%- macro row(left, right) -%}
{%- set r = (right or "") | string -%}
{%- set l = ((left or "") | string)[: 48 - (r | length) - 1] -%}
{{- l ~ (" " * (48 - (l | length) - (r | length))) ~ r ~ "\n" -}}
{%- endmacro -%}
{%- macro clean(t) -%}{{- (t or "") | string | replace("\r", "") | replace("\n", " ") | trim -}}{%- endmacro -%}
{%- macro qty(v) -%}{{- ("%g" | format((v or 0) | float)) -}}{%- endmacro -%}
{%- set is_cancel = doc.type in ("Cancelled", "Partially cancelled") -%}

{{- INIT -}}{{- CENTER -}}
{{- BOLD_ON -}}{{- BIG -}}{{- "CANCEL KOT" if is_cancel else "KOT" -}}{{- PLAIN -}}{{- BOLD_OFF -}}{{- LF -}}
{%- if doc.type and doc.type != "New Order" -%}{{- BOLD_ON -}}{{- "*** " ~ doc.type | upper ~ " ***" -}}{{- BOLD_OFF -}}{{- LF -}}{%- endif -%}
{%- if doc.production -%}{{- clean(doc.production) -}}{{- LF -}}{%- endif -%}
{%- if doc.order_no -%}{{- BOLD_ON -}}{{- BIG -}}{{- "#" ~ doc.order_no -}}{{- PLAIN -}}{{- BOLD_OFF -}}{{- LF -}}{%- endif -%}
{%- if doc.restaurant_table and not doc.table_takeaway -%}
{{- BOLD_ON -}}{{- BIG -}}{{- _("Table") ~ " " ~ doc.restaurant_table -}}{{- PLAIN -}}{{- BOLD_OFF -}}{{- LF -}}
{%- else -%}
{{- BOLD_ON -}}{{- BIG -}}{{- _("TAKE AWAY") -}}{{- PLAIN -}}{{- BOLD_OFF -}}{{- LF -}}
{%- endif -%}
{{- LEFT -}}{{- LINE -}}{{- LF -}}
{{- row(_("KOT") ~ ": " ~ doc.name, (doc.time | string)[:5]) -}}
{{- row(_("Invoice") ~ ": " ~ (doc.invoice or ""), doc.get_formatted("date")) -}}
{%- if doc.user -%}{{- row(_("By") ~ ": " ~ clean(doc.user), "") -}}{%- endif -%}
{%- if doc.customer_name -%}{{- row(_("Customer") ~ ": " ~ clean(doc.customer_name), "") -}}{%- endif -%}
{%- if doc.aggregator_id -%}{{- row(_("Aggregator ID") ~ ": " ~ doc.aggregator_id, "") -}}{%- endif -%}
{{- LINE -}}{{- LF -}}
{{- BOLD_ON -}}{{- row(_("Item"), _("Qty")) -}}{{- BOLD_OFF -}}
{{- LINE -}}{{- LF -}}
{%- for item in doc.kot_items -%}
{%- set name = clean(item.item_name or item.item) -%}
{%- if is_cancel -%}
{{- BOLD_ON -}}{{- TALL -}}{{- row("X " ~ name[:38], "-" ~ qty(item.cancelled_qty)) -}}{{- PLAIN -}}{{- BOLD_OFF -}}
{{- "   " ~ _("Remaining") ~ ": " ~ qty(item.quantity) -}}{{- LF -}}
{%- else -%}
{{- BOLD_ON -}}{{- TALL -}}{{- row(name[:40], qty(item.quantity)) -}}{{- PLAIN -}}{{- BOLD_OFF -}}
{%- if name | length > 40 -%}{{- "  " ~ name[40:86] -}}{{- LF -}}{%- endif -%}
{%- endif -%}
{%- if item.comments -%}{{- "   * " ~ clean(item.comments)[:43] -}}{{- LF -}}{%- endif -%}
{%- endfor -%}
{{- LINE -}}{{- LF -}}
{%- if doc.comments -%}{{- BOLD_ON -}}{{- _("Note") ~ ": " -}}{{- BOLD_OFF -}}{{- clean(doc.comments)[:W * 3] -}}{{- LF -}}{{- LINE -}}{{- LF -}}{%- endif -%}
{{- LF -}}{{- LF -}}{{- LF -}}
{{- CUT -}}
